    'batch07-quote-001': { finalText: 'A coragem não chega fazendo barulho; muitas vezes ela apenas impede que a dor decida por você.', label: 'UMA PERGUNTA', guidance: 'Que decisão a dor parece querer tomar sozinha?' },
