    'batch07-quote-024': { finalText: 'O eu mais profundo não precisa vencer o mundo; precisa deixar de se confundir com tudo que passa.', label: 'UMA PERGUNTA', guidance: 'Com o que passa este eu ainda parece se confundir?' },
